def completar_niveles(apps, schema_editor):
    """Insumos existentes: punto de reposición = 1,5 × mínimo; máximo = el mayor entre 4 × mínimo y el stock."""
    from decimal import Decimal

    Insumo = apps.get_model("inventario", "Insumo")
    for insumo in Insumo.objects.all():
        insumo.punto_reposicion = (insumo.stock_minimo * Decimal("1.5")).quantize(Decimal("0.001"))
        insumo.stock_maximo = max(insumo.stock_minimo * 4, insumo.stock_actual)
        insumo.save(update_fields=["punto_reposicion", "stock_maximo"])
    MovimientoStock = apps.get_model("inventario", "MovimientoStock")
    MovimientoStock.objects.filter(tipo="SAL", nota__startswith="Merma").update(tipo="MER", motivo="ANU")


